pm.collectionVariables.set('takiboHelpers', "
takibo = {
  base64Url: function (value) {
    var normalized = value.replace(/-/g, '+').replace(/_/g, '/');
    var padding = '='.repeat((4 - normalized.length % 4) % 4);
    return Buffer.from(normalized + padding, 'base64').toString('utf8');
  },
  jwt: function (token) {
    var parts = token.split('.');
    if (parts.length !== 3) {
      throw new Error('Token JWT invalide');
    }
    return JSON.parse(takibo.base64Url(parts[1]));
  },
  claimsOf: function (varName) {
    return takibo.jwt(pm.collectionVariables.get(varName));
  },
  assertErrorContract: function (expectedCode) {
    var body = pm.response.json();
    pm.expect(body.code, 'code Sentinel').to.eql(expectedCode);
    pm.expect(body.traceId, 'traceId absent du contrat d erreur').to.exist;
    pm.expect(body.status, 'status incoherent dans le corps').to.eql(pm.response.code);
    pm.expect(JSON.stringify(body), 'fuite de stacktrace').to.not.include('Exception');
  },
  require: function (names) {
    names.forEach(function (n) {
      if (!pm.collectionVariables.get(n)) {
        throw new Error('PREREQUIS MANQUANT: ' + n + ' - executer les sagas precedentes');
      }
    });
  }
};
");

